export interface Ctx { readonly id: string }
export interface Span { end(): void }
export interface Store<T> { get(): T }
export declare function within<A extends unknown[], F extends (...args: A) => ReturnType<F>>(ctx: Ctx, fn: F, ...args: A): ReturnType<F>;
export declare function inSpan<F extends (span: Span) => unknown>(name: string, fn: F): ReturnType<F>;
export declare function attempt<T>(run: (n: number) => T | PromiseLike<T>): Promise<T>;
export declare function measured<T>(run: () => T): T;
export declare function keep<T>(init: () => T): { get(): T };
export declare function store<T>(init: () => T): Store<T>;
export declare function on(event: string, listener: () => void): void;
export declare function every(ms: number, tick: () => void): number;
export declare function wrap<F extends (...args: any[]) => any>(fn: F): F;
export declare function both<T>(run: () => T, onError: (error: unknown) => void): T;
export declare function argsOf<F extends (...args: any[]) => any>(fn: F): Parameters<F>;
